private fun contractFor(config: RequestConfig): OperationContract =
    operationContracts.firstOrNull { c ->
        c.method == config.method &&
            c.path.split('/').size == config.path.split('/').size &&
            c.path.split('/').zip(config.path.split('/')).all { (a, b) ->
                a.startsWith("{") || a == b
            }
    } ?: OperationContract(config.method, config.path)

class BaseClient(
    private val apiKey: String?,
    private val store: String?,
    private val baseUrl: String,
    timeoutSeconds: Long,
    private val maxRetries: Int,
    httpClient: OkHttpClient? = null,
    private val requestHook: ((RequestEvent) -> Unit)? = null,
    private val mapper: ObjectMapper =
        jacksonObjectMapper()
            .registerModule(JavaTimeModule())
            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
            .disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES)
            .enable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_USING_DEFAULT_VALUE),
    private val accessToken: String? = null,
    private val customerSession: String? = null,
    private val browserSession: String? = null,
    private val clientId: String? = null,
    private val clientSecret: String? = null,
) {
    private val ownsClient = httpClient == null
    private val cancellableCall = ThreadLocal<AtomicReference<Call?>?>()

    init {
        require(maxRetries >= 0) { "maxRetries must be non-negative" }
        require(timeoutSeconds > 0) { "timeoutSeconds must be positive" }
    }

    private val client =
        (httpClient ?: OkHttpClient())
            .newBuilder()
            .followRedirects(false)
            .followSslRedirects(false)
            .callTimeout(Duration.ofSeconds(timeoutSeconds))
            .build()

    fun close() {
        if (ownsClient) {
            client.dispatcher.executorService.shutdown()
            client.connectionPool.evictAll()
            client.cache?.close()
        }
    }

    suspend fun <T> runCancellable(block: () -> T): T =
        suspendCancellableCoroutine { continuation ->
            val active = AtomicReference<Call?>(null)
            val future =
                client.dispatcher.executorService.submit {
                    cancellableCall.set(active)
                    try {
                        val value = block()
                        if (continuation.isActive) continuation.resume(value)
                    } catch (error: Throwable) {
                        if (continuation.isActive) continuation.resumeWithException(error)
                    } finally {
                        cancellableCall.remove()
                    }
                }
            continuation.invokeOnCancellation {
                active.get()?.cancel()
                future.cancel(true)
            }
        }

    fun customRequest(
        method: String,
        path: String,
        body: Any?,
        query: List<Pair<String, String>>,
        requestOptions: RequestOptions?,
    ): RawResponse<JsonNode> {
        require(method.matches(Regex("[A-Z]+", RegexOption.IGNORE_CASE))) {
            "method must contain only letters"
        }
        val options = (requestOptions?.copy() ?: RequestOptions())
        var captured: RawResponse<Any?>? = null
        options.responseCapture = { captured = it }
        request(
            RequestConfig(method.uppercase(), path, body, query, options, operationId = "custom"),
            JsonNode::class.java,
        )
        @Suppress("UNCHECKED_CAST")
        return captured as? RawResponse<JsonNode> ?: error("Response metadata was not captured")
    }

    fun <T> request(config: RequestConfig, responseType: Class<T>): T =
        execute(config, responseType == String::class.java) { mapper.readValue(it, responseType) }

    fun <T> request(config: RequestConfig, responseType: TypeReference<T>): T =
        execute(config) { mapper.readValue(it, responseType) }

    fun requestVoid(config: RequestConfig) {
        execute(config) { Unit }
    }

    fun <T> requestPage(
        method: String,
        path: String,
        itemType: TypeReference<T>,
        requestOptions: RequestOptions?,
        operationId: String,
        supportsIdempotency: Boolean,
        before: String?,
        after: String?,
        page: String? = null,
        itemSchema: RuntimeSchema? = null,
        visited: Set<String> = emptySet(),
        cursor: String? = null,
        buildQuery: MutableList<Pair<String, String>>.() -> Unit,
    ): Page<T> {
        if (
            (requestOptions?.maxPages ?: 1000) <= 0 ||
                requestOptions?.maxItems?.let { it <= 0 } == true
        )
            throw SellAppConfigurationException("Pagination budgets must be positive")
        val query = mutableListOf<Pair<String, String>>().apply(buildQuery)
        if (before != null) query += "before" to before
        if (after != null) query += "after" to after
        if (page != null) query += "page" to page
        if (cursor != null) {
            query.removeAll { it.first == "cursor" }
            query += "cursor" to cursor
        }
        return execute(
            RequestConfig(
                method,
                path,
                queryParams = query,
                requestOptions = requestOptions,
                operationId = operationId,
                supportsIdempotency = supportsIdempotency,
            )
        ) { json ->
            val root = mapper.readTree(json)
            val data =
                root.path("data").map {
                    if (true)
                        itemSchema?.let { schema ->
                            assertValidSchema(
                                it,
                                schema,
                                SchemaValidationOptions(
                                    "response",
                                    allowUnknownEnums = true,
                                    allowUnknownUnionVariants = true,
                                    allowUnknownFields = true,
                                ),
                            )
                        }
                    mapper.convertValue(it, itemType)
                }
            val meta = root.get("list_metadata") ?: root.get("meta")
            val links = root.get("links")
            val cursorMode = meta?.has("next_cursor") == true
            val nextCursor = textField(meta, if (cursorMode) "next_cursor" else "after")
            val currentPage = integerField(meta, "current_page")
            val lastPage = integerField(meta, "last_page")
            if (
                (currentPage != null || lastPage != null) &&
                    (currentPage == null ||
                        lastPage == null ||
                        currentPage <= 0 ||
                        lastPage <= 0 ||
                        currentPage > lastPage)
            )
                throw SellAppSerializationException(
                    "Invalid current_page/last_page pagination metadata"
                )
            val nextPage =
                if (nextCursor == null)
                    textField(links, "next")?.let { pageFromLink(it, path) }
                        ?: if (currentPage != null && lastPage != null && currentPage < lastPage)
                            (currentPage + 1).toString()
                        else null
                else null
            val key = nextCursor?.let { "after:$it" } ?: nextPage?.let { "page:$it" }
            if (key != null && (key.endsWith(":") || key in visited))
                throw SellAppSerializationException(
                    "Pagination metadata contains an empty or repeated next page"
                )
            Page(
                data,
                meta,
                links,
                key?.let {
                    {
                        if (nextCursor != null)
                            requestPage(
                                method,
                                path,
                                itemType,
                                requestOptions,
                                operationId,
                                supportsIdempotency,
                                before = null,
                                after = if (cursorMode) null else nextCursor,
                                cursor = if (cursorMode) nextCursor else null,
                                itemSchema = itemSchema,
                                visited = visited + it,
                                buildQuery = buildQuery,
                            )
                        else
                            requestPage(
                                method,
                                path,
                                itemType,
                                requestOptions,
                                operationId,
                                supportsIdempotency,
                                before = null,
                                after = null,
                                page = nextPage,
                                itemSchema = itemSchema,
                                visited = visited + it,
                                buildQuery = buildQuery,
                            )
                    }
                },
                requestOptions?.maxPages ?: 1000,
                requestOptions?.maxItems,
            )
        }
    }

    private fun textField(node: JsonNode?, field: String): String? {
        val value = node?.get(field) ?: return null
        if (value.isNull) return null
        if (!value.isTextual)
            throw SellAppSerializationException(
                "Pagination field '$field' must be a string or null"
            )
        return value.asText()
    }

    private fun integerField(node: JsonNode?, field: String): Int? {
        val value = node?.get(field) ?: return null
        if (value.isNull) return null
        if (!value.isIntegralNumber || !value.canConvertToInt())
            throw SellAppSerializationException(
                "Pagination field '$field' must be an integer or null"
            )
        return value.asInt()
    }

    private fun pageFromLink(link: String, operationPath: String): String {
        val base = runCatching {
            URI(baseUrl.trimEnd('/') + "/")
        }.getOrElse { throw SellAppSerializationException("Configured base URL is invalid", it) }
        val current = base.resolve(operationPath.trimStart('/'))
        val next = runCatching {
            if (link.startsWith("?")) URI(current.toString().substringBefore('?') + link)
            else current.resolve(URI(link))
        }
            .getOrElse {
                throw SellAppSerializationException("Pagination next link is malformed", it)
            }
        if (
            next.userInfo != null ||
                next.fragment != null ||
                !next.scheme.equals(base.scheme, true) ||
                !next.host.equals(base.host, true) ||
                next.port != base.port ||
                next.path != current.path
        )
            throw SellAppSerializationException(
                "Pagination next link leaves the configured operation"
            )
        val pages =
            next.rawQuery.orEmpty().split('&').mapNotNull { pair ->
                val parts = pair.split('=', limit = 2)
                if (URLDecoder.decode(parts[0], StandardCharsets.UTF_8) == "page")
                    URLDecoder.decode(parts.getOrElse(1) { "" }, StandardCharsets.UTF_8)
                else null
            }
        if (pages.size != 1 || !pages.single().matches(Regex("[1-9][0-9]*")))
            throw SellAppSerializationException(
                "Pagination next link must contain one positive page number"
            )
        return pages.single()
    }

    private fun <T> execute(
        config: RequestConfig,
        stringResponse: Boolean = false,
        decode: (String) -> T,
    ): T {
        val contract = contractFor(config)
        val retries = config.requestOptions?.maxRetries ?: maxRetries
        if (retries < 0) throw SellAppConfigurationException("maxRetries must be non-negative")
        if (
            config.requestOptions?.timeoutSeconds != null &&
                config.requestOptions.timeoutSeconds <= 0
        )
            throw SellAppConfigurationException("timeoutSeconds must be positive")
        if (!config.requestOptions?.idempotencyKey.isNullOrBlank() && !config.supportsIdempotency)
            throw SellAppConfigurationException(
                "This operation does not declare Idempotency-Key support"
            )
        val replayable =
            !contract.neverRetry &&
                !contract.customerSession &&
                (config.method in setOf("GET", "HEAD", "OPTIONS", "PUT", "DELETE") ||
                    config.supportsIdempotency &&
                        !config.requestOptions?.idempotencyKey.isNullOrBlank())
        var attempt = 0
        while (true) {
            val started = System.nanoTime()
            try {
                val requestClient =
                    config.requestOptions?.timeoutSeconds?.let {
                        client.newBuilder().callTimeout(Duration.ofSeconds(it)).build()
                    } ?: client
                val call = requestClient.newCall(buildRequest(config))
                cancellableCall.get()?.set(call)
                if (Thread.currentThread().isInterrupted) call.cancel()
                val response =
                    try {
                        call.execute()
                    } catch (error: java.io.IOException) {
                        if (Thread.currentThread().isInterrupted) call.cancel()
                        throw error
                    }
                try {
                    val text = response.body?.string().orEmpty()
                    if (response.code !in 200..399) {
                        if (
                            replayable &&
                                attempt < retries &&
                                (response.code == 408 ||
                                    response.code == 409 ||
                                    response.code == 429 ||
                                    response.code >= 500)
                        ) {
                            requestHook?.invoke(
                                RequestEvent(
                                    config.operationId,
                                    attempt + 1,
                                    (System.nanoTime() - started) / 1_000_000,
                                    response.code,
                                    response.header("x-request-id"),
                                    null,
                                )
                            )
                            sleepBeforeRetry(response.header("Retry-After"), attempt++)
                            continue
                        }
                        val body = runCatching { mapper.readTree(text) }.getOrNull()
                        val type = body?.get("type")?.asText()
                        val code = body?.get("code")?.asText() ?: body?.get("error")?.asText()
                        val param = body?.get("param")?.asText()
                        val requestId =
                            body?.get("request_id")?.asText() ?: response.header("x-request-id")
                        val docsUrl = body?.get("docs_url")?.asText()
                        val headers = response.headers.toMultimap()
                        val message =
                            body?.get("message")?.asText()
                                ?: body?.get("error_description")?.asText()
                                ?: "SellApp API request failed"
                        val failure =
                            when (response.code) {
                                401 ->
                                    UnauthorizedException(
                                        type,
                                        code,
                                        message,
                                        param,
                                        requestId,
                                        docsUrl,
                                        headers,
                                        text,
                                    )
                                404 ->
                                    NotFoundException(
                                        type,
                                        code,
                                        message,
                                        param,
                                        requestId,
                                        docsUrl,
                                        headers,
                                        text,
                                    )
                                429 ->
                                    RateLimitException(
                                        type,
                                        code,
                                        message,
                                        param,
                                        requestId,
                                        docsUrl,
                                        headers,
                                        text,
                                    )
                                in 500..599 ->
                                    GenericServerException(
                                        type,
                                        code,
                                        message,
                                        response.code,
                                        param,
                                        requestId,
                                        docsUrl,
                                        headers,
                                        text,
                                    )
                                else ->
                                    SellAppApiException(
                                        type,
                                        code,
                                        message,
                                        response.code,
                                        param,
                                        requestId,
                                        docsUrl,
                                        headers,
                                        text,
                                    )
                            }
                        requestHook?.invoke(
                            RequestEvent(
                                config.operationId,
                                attempt + 1,
                                (System.nanoTime() - started) / 1_000_000,
                                response.code,
                                requestId,
                                failure,
                            )
                        )
                        throw failure
                    }
                    return try {
                        val declaredText =
                            contractFor(config)
                                .textResponses
                                .filter { it.startsWith(response.code.toString() + ":") }
                                .map { it.substringAfter(":") }
                        val mediaType =
                            response.header("Content-Type")?.substringBefore(";")?.trim()
                        val isText =
                            stringResponse &&
                                declaredText.isNotEmpty() &&
                                ((text.isEmpty() && "" in declaredText) ||
                                    mediaType == null ||
                                    declaredText.any { it.equals(mediaType, ignoreCase = true) })
                        if (!isText && true && text.isNotBlank())
                            config.responseSchema?.let { schema ->
                                assertValidSchema(
                                    mapper.readTree(text),
                                    schema,
                                    SchemaValidationOptions(
                                        "response",
                                        allowUnknownEnums = true,
                                        allowUnknownUnionVariants = true,
                                        allowUnknownFields = true,
                                    ),
                                )
                            }
                        @Suppress("UNCHECKED_CAST")
                        val value = if (isText) text as T else decode(text)
                        @Suppress("UNCHECKED_CAST")
                        config.requestOptions
                            ?.responseCapture
                            ?.invoke(
                                RawResponse(
                                    value,
                                    response.code,
                                    response.headers.toMultimap(),
                                    response.header("x-request-id"),
                                    text,
                                )
                                    as RawResponse<Any?>
                            )
                        requestHook?.invoke(
                            RequestEvent(
                                config.operationId,
                                attempt + 1,
                                (System.nanoTime() - started) / 1_000_000,
                                response.code,
                                response.header("x-request-id"),
                                null,
                            )
                        )
                        value
                    } catch (e: SellAppException) {
                        requestHook?.invoke(
                            RequestEvent(
                                config.operationId,
                                attempt + 1,
                                (System.nanoTime() - started) / 1_000_000,
                                response.code,
                                response.header("x-request-id"),
                                e,
                            )
                        )
                        throw e
                    } catch (e: Exception) {
                        val failure =
                            SellAppSerializationException("Response could not be decoded", e)
                        requestHook?.invoke(
                            RequestEvent(
                                config.operationId,
                                attempt + 1,
                                (System.nanoTime() - started) / 1_000_000,
                                response.code,
                                response.header("x-request-id"),
                                failure,
                            )
                        )
                        throw failure
                    }
                } finally {
                    response.close()
                }
            } catch (e: InterruptedException) {
                Thread.currentThread().interrupt()
                throw e
            } catch (e: SocketTimeoutException) {
                requestHook?.invoke(
                    RequestEvent(
                        config.operationId,
                        attempt + 1,
                        (System.nanoTime() - started) / 1_000_000,
                        null,
                        null,
                        e,
                    )
                )
                if (replayable && attempt < retries) {
                    sleepBeforeRetry(null, attempt++)
                    continue
                }
                throw SellAppTimeoutException("Request timed out", e)
            } catch (e: SellAppException) {
                throw e
            } catch (e: Exception) {
                requestHook?.invoke(
                    RequestEvent(
                        config.operationId,
                        attempt + 1,
                        (System.nanoTime() - started) / 1_000_000,
                        null,
                        null,
                        e,
                    )
                )
                if (replayable && attempt < retries) {
                    sleepBeforeRetry(null, attempt++)
                    continue
                }
                throw SellAppTransportException("Request failed", e)
            }
        }
    }

    private fun sleepBeforeRetry(retryAfter: String?, retryNumber: Int) {
        val retryAfterMillis =
            retryAfter?.toLongOrNull()?.coerceAtLeast(0)?.times(1000)
                ?: retryAfter?.let { value ->
                    runCatching {
                        Duration.between(
                                ZonedDateTime.now(),
                                ZonedDateTime.parse(value, DateTimeFormatter.RFC_1123_DATE_TIME),
                            )
                            .toMillis()
                            .coerceAtLeast(0)
                    }
                        .getOrNull()
                }
        val exponential = (250L * (1L shl retryNumber.coerceAtMost(5))).coerceAtMost(8_000L)
        val delay =
            (retryAfterMillis
                    ?: exponential + ThreadLocalRandom.current().nextLong(exponential + 1))
                .coerceAtMost(30_000L)
        if (delay > 0) Thread.sleep(delay)
    }

    private fun buildRequest(config: RequestConfig): Request {
        val contract = contractFor(config)
        val session = config.requestOptions?.customerSession ?: customerSession
        var authorization: String? = null
        var selectedStore: String? = null
        var cookie: String? = null
        when {
            contract.customerSession && !session.isNullOrBlank() ->
                authorization = "Bearer $session"
            contract.accessToken && !accessToken.isNullOrBlank() -> {
                if (contract.accessTokenStore && store.isNullOrBlank())
                    throw SellAppConfigurationException("store is required for OAuth")
                authorization = "Bearer $accessToken"
                selectedStore = if (contract.accessTokenStore) store else null
            }
            contract.apiKey && !apiKey.isNullOrBlank() -> {
                if (contract.apiKeyStore && store.isNullOrBlank())
                    throw SellAppConfigurationException("store is required")
                authorization = "Bearer $apiKey"
                selectedStore = if (contract.apiKeyUsesStore) store else null
            }
            contract.browserSession && !browserSession.isNullOrBlank() -> cookie = browserSession
            contract.clientBasic && !clientId.isNullOrBlank() ->
                authorization =
                    "Basic " +
                        java.util.Base64.getEncoder()
                            .encodeToString(
                                (URLEncoder.encode(clientId, StandardCharsets.UTF_8) +
                                        ":" +
                                        URLEncoder.encode(
                                            clientSecret.orEmpty(),
                                            StandardCharsets.UTF_8,
                                        ))
                                    .toByteArray(StandardCharsets.UTF_8)
                            )
            !contract.anonymous ->
                throw SellAppConfigurationException(
                    "Credentials required by this operation are missing"
                )
        }
        val rawPath = runCatching {
            URI(config.path)
        }.getOrElse { throw SellAppConfigurationException("Request path is malformed") }
        if (
            rawPath.isAbsolute ||
                rawPath.rawAuthority != null ||
                rawPath.userInfo != null ||
                rawPath.fragment != null
        )
            throw SellAppConfigurationException(
                "Request path must be relative and contain no authority, credentials, or fragment"
            )
        val selectedBase =
            if (contract.server.isNotEmpty()) {
                if (baseUrl == "https://sell.app/api") contract.server
                else
                    baseUrl.toHttpUrl().newBuilder().encodedPath("/").query(null).build().toString()
            } else baseUrl
        val apiBase = (selectedBase.trimEnd('/') + "/").toHttpUrl()
        val url =
            apiBase
                .resolve(config.path.trimStart('/'))
                ?.newBuilder()
                ?.apply { config.queryParams.forEach { addQueryParameter(it.first, it.second) } }
                ?.build()
                ?: throw SellAppConfigurationException("Request path could not be resolved")
        if (url.scheme != apiBase.scheme || url.host != apiBase.host || url.port != apiBase.port)
            throw SellAppConfigurationException("Request path leaves the configured API origin")
        val body =
            if (config.body == null) null
            else
                try {
                    if (config.bodyEncoding == "form-data") multipartRequestBody(config.body)
                    else {
                        val encoded = mapper.writeValueAsString(config.body)
                        val tree = mapper.readTree(encoded)
                        if (true)
                            config.requestSchema?.let { schema ->
                                assertValidSchema(tree, schema, SchemaValidationOptions("request"))
                            }
                        if (contract.form) {
                            if (
                                contract.clientBasic &&
                                    authorization?.startsWith("Basic ") == true &&
                                    (tree.has("client_id") || tree.has("client_secret"))
                            )
                                throw SellAppConfigurationException(
                                    "Use Basic or body credentials, never both"
                                )
                            FormBody.Builder()
                                .apply {
                                    tree.fields().forEachRemaining { (name, value) ->
                                        if (value.isArray)
                                            value.forEach { add(name + "[]", it.asText()) }
                                        else if (!value.isNull) add(name, value.asText())
                                    }
                                }
                                .build()
                        } else encoded.toRequestBody(JSON)
                    }
                } catch (e: SellAppException) {
                    throw e
                } catch (e: Exception) {
                    throw SellAppSerializationException("Request body could not be encoded", e)
                }
        return Request.Builder()
            .url(url)
            .method(
                config.method,
                if (config.method in setOf("POST", "PUT", "PATCH") && body == null)
                    "{}".toRequestBody(JSON)
                else body,
            )
            .apply {
                config.requestOptions?.idempotencyKey?.let { key ->
                    this.header("Idempotency-Key", key)
                }
                config.requestOptions?.headers?.forEach { (k, v) -> this.header(k, v) }
            }
            .removeHeader("Authorization")
            .removeHeader("X-STORE")
            .removeHeader("Cookie")
            .apply {
                authorization?.let { header("Authorization", it) }
                selectedStore?.takeIf { it.isNotBlank() }?.let { header("X-STORE", it) }
                cookie?.let { header("Cookie", it) }
            }
            .header("User-Agent", "SellApp kotlin/0.1.1")
            .build()
    }

    private fun multipartRequestBody(value: Any): RequestBody {
        val builder = MultipartBody.Builder().setType(MultipartBody.FORM)
        val fields = value as? Map<*, *> ?: mapper.convertValue(value, Map::class.java)
        fun add(name: String, item: Any?) {
            when (item) {
                null -> Unit
                is ByteArray ->
                    builder.addFormDataPart(
                        name,
                        name,
                        item.toRequestBody("application/octet-stream".toMediaType()),
                    )
                is File ->
                    builder.addFormDataPart(
                        name,
                        item.name,
                        item.asRequestBody("application/octet-stream".toMediaType()),
                    )
                is Path -> {
                    val file = item.toFile()
                    builder.addFormDataPart(
                        name,
                        file.name,
                        file.asRequestBody("application/octet-stream".toMediaType()),
                    )
                }
                is InputStream -> {
                    if (!item.markSupported())
                        throw SellAppConfigurationException(
                            "multipart input streams must support mark/reset for safe retries"
                        )
                    item.mark(Int.MAX_VALUE)
                    val streamBody =
                        object : RequestBody() {
                            override fun contentType() = "application/octet-stream".toMediaType()

                            override fun writeTo(sink: BufferedSink) {
                                item.reset()
                                sink.writeAll(item.source())
                                item.reset()
                            }
                        }
                    builder.addFormDataPart(name, name, streamBody)
                }
                is Iterable<*> -> item.forEach { add(name, it) }
                else -> builder.addFormDataPart(name, item.toString())
            }
        }
        fields.forEach { (name, item) -> add(name.toString(), item) }
        return builder.build()
    }

    companion object {
        private val JSON = "application/json".toMediaType()
    }
}
